const DEPARTMENTS = {
  Engineering: [
    { id: 'eng-001', name: 'Aisha' },
    { id: 'eng-002', name: 'Ben' },
    { id: 'eng-003', name: 'Carla' },
  ],
  Design: [
    { id: 'des-001', name: 'Diana' },
    { id: 'des-002', name: 'Evan' },
  ],
  Sales: [
    { id: 'sal-001', name: 'Farah' },
