      } else if (n < 10) {
        expect(isBlue(color), `expected ${n} to be blue, got ${color}`).to.equal(true);
      } else {
        expect(isRed(color) || isBlue(color), `expected ${n} to be neither red nor blue, got ${color}`).to.equal(false);
